 'r-portal':{zh:'自助门户',en:'Self-service\nportal',lines:['r-self'],pos:{rafay:1},tag:'rafay',lv:1,st:'wip',
  d:['用户在一个统一的界面里申请 Kubernetes 集群、虚拟机、AI 工作区和推理环境。','Users request Kubernetes clusters, VMs, AI workspaces and inference environments from one interface.']},
 'r-vm':{zh:'虚拟机',en:'Virtual\nmachines',lines:['r-self'],pos:{rafay:3},tag:'rafay',lv:1,st:'wip',
  d:['除了容器集群，也能自助交付虚拟机。','Besides container clusters, virtual machines can be delivered self-service too.']},
 'r-mt':{zh:'多租户',en:'Multi-tenancy',lines:['r-self','r-gov'],pos:{rafay:4},tag:'rafay',lv:1,st:'wip',
  d:['很多租户共用同一套 GPU 基础设施，各自自助取用，由平台统一治理。','Many tenants share one GPU infrastructure, each serving itself, all governed by the platform.']},

