 'r-plat':{zh:'Rafay\nPlatform',en:'Rafay\nPlatform',t:['Rafay Platform：GPU 云的控制平面','Rafay Platform: the control plane for a GPU cloud'],lines:['r-cp'],pos:{rafay:0},tag:'rafay',lv:1,st:'wip',
  d:['把裸 GPU 基础设施变成可以自助使用、多租户、可运营的 AI 云的控制平面。','A control plane that turns bare GPU infrastructure into a self-service, multi-tenant AI cloud that can be operated.']},
